import{_ as e,o as r,c as t,aQ as i}from"./chunks/framework.C8WmN7-d.js";const u=JSON.parse('{"title":"Obsidian","description":"","frontmatter":{"order":-1},"headers":[],"relativePath":"others/obsidian/index.md","filePath":"others/obsidian/index.md"}'),o={name:"others/obsidian/index.md"};function n(d,a,l,s,h,b){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="obsidian" tabindex="-1">Obsidian <a class="header-anchor" href="#obsidian" aria-label="Permalink to &quot;Obsidian&quot;">​</a></h1><p><a href="https://obsidian.md/" target="_blank" rel="noreferrer">Obsidian</a> 是一款以本地 Markdown 文件为核心的知识库与笔记应用，支持双向链接、关系图谱、插件扩展与多设备同步，适合个人知识管理与长期写作沉淀。</p><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h2><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h3><ul><li><strong>桌面端</strong>：在 <a href="https://obsidian.md/download" target="_blank" rel="noreferrer">obsidian.md/download</a> 下载 Windows / macOS / Linux 客户端。</li><li><strong>移动端</strong>：App Store / Google Play 搜索 Obsidian，与桌面端通过官方同步或第三方方案联动。</li></ul><h3 id="基本流程" tabindex="-1">基本流程 <a class="header-anchor" href="#基本流程" aria-label="Permalink to &quot;基本流程&quot;">​</a></h3><ol><li><strong>创建仓库（Vault）</strong>：首次打开选择或新建一个本地文件夹作为笔记库，所有 <code>.md</code> 文件保存在该目录。</li><li><strong>写笔记</strong>：新建笔记即 Markdown 文件，支持 <code>[[双向链接]]</code>、<code>#标签</code>、代码块、公式等。</li><li><strong>图谱与反向链接</strong>：通过关系图谱查看笔记关联；右侧面板可查看当前笔记的入链与出链。</li><li><strong>插件与主题</strong>：设置 →「第三方插件」→ 开启社区插件市场，按需安装日历、模板、Dataview 等扩展。</li></ol><h3 id="与本文档站的关系" tabindex="-1">与本文档站的关系 <a class="header-anchor" href="#与本文档站的关系" aria-label="Permalink to &quot;与本文档站的关系&quot;">​</a></h3><p>本站基于 VitePress + Markdown 构建，Obsidian 同样以 Markdown 为底层格式，适合：</p><ul><li>在 Obsidian 中起草、整理碎片笔记</li><li>成熟内容再迁移或同步到 VitePress 文档库发布</li></ul><h2 id="导航" tabindex="-1">导航 <a class="header-anchor" href="#导航" aria-label="Permalink to &quot;导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>说明</th></tr></thead><tbody><tr><td><a href="/others/obsidian/fast-note-sync/">Fast Note Sync</a></td><td>多端实时同步插件，需配合自托管服务端</td></tr></tbody></table><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="https://obsidian.md/" target="_blank" rel="noreferrer">Obsidian 官网</a></li><li><a href="https://help.obsidian.md/" target="_blank" rel="noreferrer">Obsidian 帮助文档</a></li><li><a href="https://obsidian.md/plugins" target="_blank" rel="noreferrer">Obsidian 社区插件</a></li><li><a href="https://github.com/obsidianmd" target="_blank" rel="noreferrer">Obsidian GitHub 主题与示例</a></li></ul>',14)])])}const f=e(o,[["render",n]]);export{u as __pageData,f as default};
